// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: the caller who will attempt to transfer ownership
    function testFuzz_property(address caller) public {
        // keep caller wide-ranging but not zero for meaningful impersonation
        vm.assume(caller != address(0));

        // initialize contract so owner is set to deployer (address(this))
        c.initialize();

        // sanity: the current owner should be this contract (deployer in setUp)
        assertTrue(c.owner() == address(this));

        // The property: when the current owner calls transferOwnership(address(0)),
        // the reference contract enforces that setting owner to zero address is disallowed
        // so the external call should revert / fail. We'll invoke transferOwnership
        // from the rightful owner (this) and detect whether the call succeeded.

        bool ok;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exact one assertion: In the correct contract, attempting to transfer ownership
        // to the zero address must fail, therefore ok must be false for ALL inputs.
        // The mutant removing the require will make ok == true for some inputs
        // (specifically here when the caller is the owner), causing this assertion to fail.
        assertTrue(!ok);
    }
}

