pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter: a candidate newOwner address. The rule must hold for all inputs
    // on the reference implementation: after transferOwnership(newOwner) by the current
    // owner, c.owner() == newOwner. The mutant that zeroes old owner before transfer
    // will break this for some inputs (notably when newOwner != address(0)).
    function testFuzz_property(address newOwner) public {
        // keep domain wide but exclude zero address for newOwner? We allow zero as valid
        // because reference allows renouncing by transfer to address(0) only via renounceOwnership
        // but transferOwnership requires newOwner != address(0) so we must assume nonzero.
        vm.assume(newOwner != address(0));

        // initialize contract so msg.sender becomes owner
        c.initialize();

        // current owner should be this test contract (address(this))
        // now call transferOwnership as the owner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation: transferOwnership requires onlyOwner and nonzero newOwner,
        // so call should succeed (ok == true) and owner() must equal newOwner for all admissible inputs.
        // The mutant may alter the internal state update such that owner() is not newOwner for some inputs.
        assertTrue(ok && c.owner() == newOwner);
    }
}

