pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer = address(1);

    function setUp() public {
        // deploy C as deployer (owner will be deployer due to __Ownable_init_unchained calling _msgSender())
        vm.prank(deployer);
        c = new C();
        // initialize to set owner
        vm.prank(deployer);
        c.initialize();
    }

    // General rule: Only the current owner (deployer) can successfully call transferOwnership(newOwner),
    // and after the call completes owner() must equal newOwner. The mutant sometimes corrupts ownership transition
    // by zeroing previous owner state and may still set owner(), but the correct contract always sets owner() to newOwner
    // when invoked by the current owner. We fuzz the newOwner address.
    function testFuzz_property(address newOwner) public {
        // Keep newOwner wide but avoid zero address because transferOwnership in reference rejects zero address
        // (reference requires newOwner != address(0)). We still allow zero to be fuzzed — in that case call should revert.
        // So we don't assume nonzero to allow both branches; we will call as owner and observe behavior via try/catch.

        // Act as current owner (deployer) when calling transferOwnership
        vm.prank(deployer);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: If call succeeded (ok==true) then owner() must equal newOwner.
        // This is a universal property the reference satisfies for all inputs; the mutant will fail for some input
        // because it tampers with owner transition sequence.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reverted, then owner must remain the previous owner (deployer)
            assertTrue(c.owner() == deployer);
        }
    }
}

