        // as that owner directly.

        // Call transferOwnership with the fuzzed proposedNewOwner and capture if it succeeded.
        bool ok;
        try c.transferOwnership(proposedNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the call succeeded, owner() must equal the proposedNewOwner.
