pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: owner EOA and a newOwner address to transfer to
    // We will deploy a helper contract Forwarder that does a call into c.transferOwnership
    // using msg.sender being the Forwarder contract and tx.origin being the EOA owner.
    function testFuzz_property(address ownerEoa, address newOwner) public {
        // Keep addresses canonical: non-zero owner and newOwner not equal to current owner is allowed
        vm.assume(ownerEoa != address(0));
        vm.assume(newOwner != address(0));

        // Initialize contract as if ownerEoa is the deployer / initializer
        // The contract uses OwnableUpgradeable initializer: calling initialize sets owner to _msgSender()
        // So we prank as ownerEoa to initialize
        vm.prank(ownerEoa);
        c.initialize();

        // Ensure at this point owner() == ownerEoa
        assert(c.owner() == ownerEoa);

        // Deploy a forwarder contract that will call c.transferOwnership(newOwner)
        Forwarder f = new Forwarder(c);

        // Case A: direct call by EOA owner should succeed on both reference and mutant
        // We simulate the EOA calling transferOwnership directly
        bool okDirect;
        try c.transferOwnership{gas: gasleft()}(newOwner) {
            okDirect = true;
        } catch {
            okDirect = false;
        }
        // Reinitialize owner back to ownerEoa for the forwarding test if direct succeeded
        if (okDirect) {
            // If direct succeeded, ownership has changed to newOwner; set it back by having newOwner reinitialize ownership
            // But we cannot reinitialize; instead, set up the contract again by deploying a fresh instance for the forwarder test.
            // To comply with the requirement to observe the same contract instance, we instead avoid letting the direct call change state:
            // So revert state change by performing tests in a fork-neutral way: we reset by re-deploying c in setUp only once — workaround: require direct call to be done under a prank that uses ownerEoa, but we can avoid state mutation by expecting that direct call is allowed and then recreate c.
            // Simpler: deploy a fresh contract and set it up again for forwarding scenario.
            c = new C();
            vm.prank(ownerEoa);
            c.initialize();
            // redeploy forwarder to point to the new c
            f = new Forwarder(c);
        }

        // Now perform the forwarded call: the EOA (ownerEoa) sends a transaction to Forwarder which calls c.transferOwnership(newOwner)
        // tx.origin will be ownerEoa, but msg.sender inside c will be the Forwarder contract.
        vm.prank(ownerEoa);
        bool okForwarded = f.doTransferOwnership(newOwner);

        // General rule to assert: In the reference contract, only an EOA equal to owner() (i.e., msg.sender == owner) can succeed; a forwarded call where msg.sender != owner should fail — so okForwarded must be false in the reference.
        // The mutant that uses tx.origin will allow the forwarded call (okForwarded == true) for some inputs (when tx.origin == owner), causing this assertion to fail.
        assertTrue(!okForwarded);
    }
}

// Minimal adversarial helper that forwards a call into the factory contract
contract Forwarder {
    C target;
    constructor(C _target) {
        target = _target;
    }

    // returns true if the forwarded call succeeded, false if it reverted
    function doTransferOwnership(address newOwner) external returns (bool) {
        // low-level call to propagate success/failure
        (bool success, ) = address(target).call(abi.encodeWithSelector(target.transferOwnership.selector, newOwner));
        return success;
    }
}

