pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz params: owner EOA and a prospective caller address (we will deploy a forwarding helper at that caller address)
    function testFuzz_property(address ownerEOA, uint256 salt) public {
        // Keep domain wide but avoid zero owner which is possible but fine; allow any owner
        vm.assume(ownerEOA != address(0));

        // 1) Initialize c so that owner() == address(this) initially via initialize()
        // initialize sets owner to msg.sender; we want ownerEOA to be the owner, so we must simulate ownerEOA calling initialize()
        // Deploy a tiny helper that can call initialize on c as an EOA via prank.
        vm.prank(ownerEOA);
        c.initialize();
        // Confirm owner is ownerEOA
        assertTrue(c.owner() == ownerEOA);

        // 2) Construct a forwarding contract deployed at an address derived from salt so fuzzer controls it
        // Deploy Forwarder which will call c.transferOwnership(...) on behalf of tx.origin (ownerEOA)
        Forwarder f = new Forwarder(c);

        // 3) Choose a newOwner target to transfer to. Use salt to vary it but not hard-code any address literal.
        // Construct newOwner derived from salt (but not too restrictive)
        address newOwner = address(uint160(uint256(keccak256(abi.encodePacked(salt, ownerEOA)))));
        vm.assume(newOwner != address(0));

        // 4) Scenario: ownerEOA is the EOA owner; attempt to have the Forwarder call transferOwnership on c.
        // For the reference contract (which checks msg.sender == owner), only if the caller's msg.sender equals ownerEOA
        // will transfer succeed. Here Forwarder will be the msg.sender, and tx.origin will be ownerEOA (because we prank ownerEOA).

        // Make the call originate from ownerEOA so tx.origin == ownerEOA and msg.sender == address(f)
        vm.prank(ownerEOA);
        bool ok;
        try f.callTransferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single universal assertion: In the correct contract, only the actual caller equal to owner() (msg.sender == owner)
        // can effect ownership transfer when called — therefore, when a contract (Forwarder) calls while tx.origin == ownerEOA,
        // the correct contract MUST reject (ok == false). The mutant which checks tx.origin will accept (ok == true) for some inputs.
        // We assert the property the reference satisfies for ALL inputs: the forwarder call must NOT have changed ownership in the reference.
        // Observe via c.owner() getter: it must still equal ownerEOA.
        assertTrue(c.owner() == ownerEOA);
    }
}

// Minimal adversarial helper: forwards a call to c.transferOwnership(newOwner)
contract Forwarder {
    C public c;
    constructor(C _c) {
        c = _c;
    }
    function callTransferOwnership(address newOwner) external {
        // Forward the external call to c. This makes msg.sender == address(this) for c and tx.origin preserved from the original EOA.
        c.transferOwnership(newOwner);
    }
}

