pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an EOA owner and a different attacker/newOwner candidate
    function testFuzz_property(address nativeOwner, address proxyCaller) public {
        vm.assume(nativeOwner != address(0));
        vm.assume(proxyCaller != address(0));
        vm.assume(nativeOwner != proxyCaller);

        // 1) initialize c so nativeOwner becomes owner via the initializer flow
        // __Ownable_init_unchained sets owner to _msgSender(); we need to call initialize from nativeOwner
        vm.prank(nativeOwner);
        c.initialize();

        // Confirm owner getter equals nativeOwner
        address beforeOwner = c.owner();
        assertEq(beforeOwner, nativeOwner);

        // 2) Deploy a malicious forwarding contract whose msg.sender will be the forwarding contract
        // but tx.origin will be nativeOwner when we have the EOA call it. This models an external contract
        // forwarding a call on behalf of the EOA owner — the correct contract requires msg.sender == owner
        // so only a direct call from nativeOwner should succeed; the mutant checking tx.origin would allow
        // the forwarder to succeed when nativeOwner is the tx.origin.
        Forwarder f = new Forwarder(address(c));

        // choose a new owner that is the proxyCaller (fuzzed)
        address newOwner = proxyCaller;
        vm.assume(newOwner != nativeOwner);

        // 3) Attempt transferOwnership via the forwarder but initiated by nativeOwner as tx.origin
        // The forwarder will call c.transferOwnership(newOwner) such that msg.sender==address(f) and tx.origin==nativeOwner
        // Catch whether the external call succeeded (ok == true) or reverted (ok == false).
        bool ok;
        // make the external EOA nativeOwner be the tx.origin for the forwarded call
        vm.prank(nativeOwner);
        try f.forwardTransferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the attempt, read c.owner() exactly once and assert the universal property:
        // In the reference contract, only a direct call from the owner (msg.sender == owner) can change ownership.
        // Therefore, a forwarded call (msg.sender == forwarder) initiated by the owner EOA should NOT change owner
        // because msg.sender != owner; so owner must remain nativeOwner regardless of ok.
        // The mutant that checks tx.origin instead will allow this forwarded call to succeed (ok==true) and change owner.
        // We assert the property: owner stayed nativeOwner.
        assertTrue(c.owner() == nativeOwner);
    }
}

contract Forwarder {
    address target;
    constructor(address _t) { target = _t; }
    // called by an EOA tx.origin; this forwards to target.transferOwnership(newOwner)
    function forwardTransferOwnership(address newOwner) external {
        // use low-level call to match external call semantics
        (bool s, bytes memory) = address(target).call(abi.encodeWithSelector(C.transferOwnership.selector, newOwner));
        if (!s) {
            // propagate revert to let try/catch in test observe it
            assembly { revert(add(32, mload(0x40)), 0) }
        }
    }
}

